	function validateCurrentStep() {
		$.set(errors, {}, true);

		switch ($store().currentStep) {
			case "basics":
				if (!$store().task.title?.trim()) $.get(errors).title = "Title is required";
				if ($store().task.dateRange) {
					if (!$store().task.dateRange.end && !$store().task.dateRange.start) {
