			case "location":
				if ($store().isRemovals) {
					if (!$store().task.pickupLocation?.latitude || !$store().task.pickupLocation?.longitude) {
						$.get(errors).location = "Pickup location is required for this task";
					}

					if (!$store().task.dropOffLocation?.latitude || !$store().task.dropOffLocation?.longitude) {
						$.get(errors).location = "Drop-off location is required for this task";
					}
				}
				if ($store().task.taskType === TaskTypeEnum.IN_PERSON && (!$store().task.pickupLocation?.latitude || !$store().task.pickupLocation?.longitude)) {
					$.get(errors).location = "Location is required for this task";
				}
				break;

			case "budget":
				if (!$store().task.budget.amount || $store().task.budget.amount <= 0) {
					$.get(errors).budget = "Valid budget is required";
				}
				if ($store().task.budget.type === BudgetTypeEnum.HOURLY && (!$store().task.budget.estimatedHours || $store().task.budget.estimatedHours <= 0)) {
					$.get(errors).estimatedHours = "Estimated hours must be greater than 0";
				}
				if (!$store().task.description?.trim()) $.get(errors).description = "Description is required";
				if ($store().task.description?.trim().length < 20) $.get(errors).description = "Description must be at least 20 characters long";
				break;

			case "taskboost":
				break;

			case "review":
				break;
		}

		return Object.keys($.get(errors)).length === 0;
	}

